const MAX_IMAGE=10*1024*1024,MAX_VIDEO=50*1024*1024;
function waitFor(target,event,timeout=15000){return new Promise((resolve,reject)=>{const timer=setTimeout(()=>done(Error('读取媒体超时，请换一个文件')),timeout),success=()=>done(),failure=()=>done(Error('当前浏览器无法读取此媒体，请使用常见 PNG、JPEG、WebP、MP4 或 WebM'));function done(error){clearTimeout(timer);target.removeEventListener(event,success);target.removeEventListener('error',failure);error?reject(error):resolve();}target.addEventListener(event,success,{once:true});target.addEventListener('error',failure,{once:true});});}
async function prepare(file){
 if(file.type.startsWith('image/')){if(file.size>MAX_IMAGE)throw Error('图片最大 10 MB');const bitmap=await createImageBitmap(file),canvas=document.createElement('canvas'),scale=Math.min(1,1600/Math.max(bitmap.width,bitmap.height));canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const blob=await new Promise(r=>canvas.toBlob(r,'image/webp',.88));if(!blob)throw Error('无法处理图片');return {blob,kind:'image'};}
 if(!['video/mp4','video/webm'].includes(file.type))throw Error('视频请使用 MP4 或 WebM');if(file.size>MAX_VIDEO)throw Error('视频最大 50 MB');
 const url=URL.createObjectURL(file),video=document.createElement('video');video.muted=true;video.preload='auto';video.playsInline=true;
 try{const loaded=waitFor(video,'loadeddata');video.src=url;await loaded;const duration=video.duration;if(!Number.isFinite(duration)||duration<=0||duration>300)throw Error('视频时长需在 5 分钟以内');const canvas=document.createElement('canvas'),scale=Math.min(1,640/Math.max(video.videoWidth,video.videoHeight));canvas.width=Math.max(1,Math.round(video.videoWidth*scale));canvas.height=Math.max(1,Math.round(video.videoHeight*scale));const frames=[],count=Math.min(8,Math.max(2,Math.ceil(duration/5)+1));for(let i=0;i<count;i++){const time=i/(count-1)*Math.max(0,duration-.05);if(Math.abs(video.currentTime-time)>.01){const seeked=waitFor(video,'seeked');video.currentTime=time;await seeked;}canvas.getContext('2d').drawImage(video,0,0,canvas.width,canvas.height);frames.push({time,data:canvas.toDataURL('image/jpeg',.8)});}return {blob:file,kind:'video',duration,frames};}finally{video.pause();video.removeAttribute('src');video.load();URL.revokeObjectURL(url);}
}
export function createMediaComposer({button,preview,apiBase='/social-api',onNotice=()=>{},onChange=()=>{}}){
 if(!document.getElementById('uoya-media-css')){const link=document.createElement('link');link.id='uoya-media-css';link.rel='stylesheet';link.href=new URL('./media.css',import.meta.url).href;document.head.append(link);}
 const picker=document.createElement('input');picker.type='file';picker.accept='image/png,image/jpeg,image/webp,image/gif,video/mp4,video/webm';picker.multiple=true;picker.hidden=true;button.after(picker);let records=[],frozen=false;
 async function request(path,options){const response=await fetch(apiBase+path,{credentials:'include',...options});let data={};try{data=await response.json();}catch{}if(!response.ok)throw Error(data.error||'附件上传失败');return data;}
 function render(){preview.replaceChildren();preview.hidden=!records.length;button.disabled=frozen;for(const record of records){const row=document.createElement('div');row.className='uoya-media-draft';const thumb=document.createElement(record.file.type.startsWith('video/')?'video':'img');thumb.src=record.url;if(thumb.tagName==='VIDEO'){thumb.muted=true;thumb.preload='metadata';}const copy=document.createElement('span');copy.textContent=record.file.name;copy.title=record.file.name;const status=document.createElement('small');status.textContent=record.state==='ready'?'':record.state==='error'?record.error:'处理中…';const remove=document.createElement('button');remove.type='button';remove.textContent='×';remove.setAttribute('aria-label','移除 '+record.file.name);remove.disabled=frozen;remove.onclick=()=>{record.controller?.abort();URL.revokeObjectURL(record.url);records=records.filter(r=>r!==record);render();};row.append(thumb,copy,status,remove);if(record.state==='error'){const retry=document.createElement('button');retry.type='button';retry.textContent='重试';retry.disabled=frozen;retry.onclick=()=>void process(record);row.append(retry);}preview.append(row);}onChange();}
 async function process(record){record.state='busy';record.error='';record.controller=new AbortController();render();try{const data=await prepare(record.file);if(!records.includes(record))return;let {attachment}=await request('/api/uploads?name='+encodeURIComponent(record.file.name.slice(0,160)),{method:'POST',headers:{'Content-Type':data.blob.type},body:data.blob,signal:record.controller.signal});if(data.kind==='video')({attachment}=await request('/api/uploads/'+attachment.id+'/frames',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({duration:data.duration,frames:data.frames}),signal:record.controller.signal}));record.attachment=attachment;record.state='ready';}catch(error){if(records.includes(record)){record.state='error';record.error=error.message;onNotice(error.message,true);}}finally{if(records.includes(record))render();}}
 button.onclick=()=>{if(!frozen)picker.click();};picker.onchange=()=>{for(const file of picker.files){if(records.length>=4){onNotice('每条消息最多 4 个附件',true);break;}const record={file,url:URL.createObjectURL(file),state:'busy'};records.push(record);void process(record);}picker.value='';};
 return {get ids(){return records.filter(r=>r.state==='ready').map(r=>r.attachment.id);},get busy(){return records.some(r=>r.state==='busy');},get hasErrors(){return records.some(r=>r.state==='error');},freeze(value){frozen=value;render();},clear(){for(const record of records){record.controller?.abort();URL.revokeObjectURL(record.url);}records=[];render();}};
}
